  "Pendiente de aceptación": "bg-rose-50 text-rose-700 ring-rose-200",
  "En proceso": "bg-amber-50 text-amber-700 ring-amber-200",
  "Entregado": "bg-emerald-50 text-emerald-700 ring-emerald-200",
