        setCarrosPersianas(resultados.carrosPersianas ? toArray(resultados.carrosPersianas) : carrosPersianasPorDefecto());
        if (resultados.persianasAlmacen) setPersianasAlmacen(toArray(resultados.persianasAlmacen));
