          // Si todavía no hay ningún techo guardado, se enseñan los de fábrica (no se guardan hasta que se toque algo).
          let lista = guardados.some((m) => m.categoria === "techo") ? guardados : [...guardados, ...modelosTechoDeFabrica()];
